def is_valid_tournament(m, n, points):
    if n == 1:
        return points[0] <= 2 * (m - 1)

    if points[0] > 2 * (m - 1) or points[-1] < 0:
        return False

    for i in range(1, n):
        if points[i] > points[i - 1] or points[i] < 2 * (n - i - 1):
            return False

    return True

def construct_tournament(m, n, points):
    if not is_valid_tournament(m, n, points):
        return "no"

    # Initialize the tournament matrix with 'X' on the diagonal
    tournament = [['X'] * m for _ in range(m)]

    # Fill the upper triangle with 'W' and 'L'
    for i in range(m):
        for j in range(i + 1, m):
            if points[i] > points[j]:
                tournament[i][j] = 'W'
                tournament[j][i] = 'L'
            else:
                tournament[i][j] = 'L'
                tournament[j][i] = 'W'

    # Adjust the points to match the required values
    for i in range(n):
        while points[i] > 2 * (m - 1 - i):
            for j in range(i + 1, m):
                if tournament[i][j] == 'W':
                    tournament[i][j] = 'D'
                    tournament[j][i] = 'D'
                    points[i] -= 1
                    points[j] -= 1

    return "yes", tournament

